export const seed = () => ({version:1, running:true,profile:{name:'陈律师',city:'上海',field:'劳动争议',style:'专业、亲和，使用清晰的口语表达',intro:'专注劳动争议与用工合规，为劳动者与企业提供咨询服务。',knowledge:'咨询前需要准备什么？\n请先整理劳动合同、相关通知和沟通记录，具体材料由律师确认。'},contents:[{id:'c1',title:'公司口头辞退，还要去上班吗？',stage:'script',source:'来自近期 5 次咨询',body:'开场：公司口头通知你不用来上班，下一步应该先了解什么？\n\n核心观点：先梳理通知方式、合同情况和自己的诉求，再由专业人士结合具体情况判断。\n\n结尾：你最关心哪一类劳动争议问题？欢迎留言。',format:'抖音视频'},{id:'c2',title:'签劳动合同前，先看这三个地方',stage:'review',source:'专业经验',body:'开场：签署劳动合同前，你会重点查看哪些内容？\n\n核心观点：围绕工作安排、报酬约定和合同期限，分享审核思路。\n\n结尾：具体问题请结合材料向专业人士咨询。',format:'小红书图文'},{id:'c3',title:'咨询律师前，可以提前准备什么？',stage:'approved',source:'常见咨询问题',body:'整理事情经过、相关材料，以及最希望解决的问题，让第一次沟通更高效。',format:'抖音视频'}],posts:[{id:'p1',contentId:'c3',platform:'抖音',at:'2026-11-18T14:00',status:'scheduled'}],conversations:[{id:'q1',name:'客户 A',need:'劳动合同解除咨询',platform:'抖音',contentId:'c1',match:'初步匹配',intent:'待确认',manual:false,messages:[{who:'client',text:'公司口头通知我下周不用来了，我想了解下一步应该准备什么。'},{who:'agent',text:'我先帮您整理情况，方便律师了解。您在哪个城市？是否收到了书面通知？'},{who:'client',text:'在上海，还没有书面通知，希望能预约沟通。'}]},{id:'q2',name:'客户 B',need:'劳动合同条款咨询',platform:'小红书',contentId:'c2',match:'初步匹配',intent:'明确',manual:false,messages:[{who:'client',text:'最近要签一份劳动合同，想预约律师帮忙看看。'},{who:'agent',text:'已记录您的需求，后续由律师确认服务范围与预约时间。'}]}],leads:[{id:'l1',conversationId:null,name:'客户 C',need:'劳动争议咨询',platform:'抖音',contentId:'c1',stage:'待跟进',intent:'明确',appointment:'',history:['2026-11-16 · 已确认咨询诉求'],reason:''},{id:'l2',conversationId:null,name:'客户 D',need:'劳动合同审核',platform:'小红书',contentId:'c2',stage:'已预约',intent:'明确',appointment:'2026-11-18T14:30',history:['2026-11-15 · 已确认视频咨询时间'],reason:''}],});
export function transitionContent(content,next){const allowed={script:['production'],production:['review','script'],review:['approved','script'],approved:[]};if(!allowed[content.stage]?.includes(next))throw new Error('请按内容流程完成上一步');content.stage=next;}
export function convertLead(state,conversation){const existing=state.leads.find(l=>l.conversationId===conversation.id);if(existing)return existing;const lead={id:'l'+Date.now(),conversationId:conversation.id,name:conversation.name,need:conversation.need,platform:conversation.platform,contentId:conversation.contentId,stage:'待跟进',intent:conversation.intent,appointment:'',history:['2026-11-16 · 从接待会话转为线索'],reason:''};state.leads.push(lead);return lead;}
export function schedulePost(state,contentId,platform,at){if(state.contents.find(c=>c.id===contentId)?.stage!=='approved')throw new Error('只有已审核内容可以排期');if(!['抖音','小红书'].includes(platform)||!at||Number.isNaN(Date.parse(at)))throw new Error('请填写有效的平台和发布时间');if(state.posts.some(p=>p.contentId===contentId&&p.platform===platform&&p.status==='scheduled'))throw new Error('该内容在此平台已有排期');state.posts.push({id:'p'+Date.now(),contentId,platform,at,status:'scheduled'});}
export function bookAppointment(lead,at){if(!at||Number.isNaN(Date.parse(at)))throw new Error('请填写有效预约时间');lead.appointment=at;lead.stage='已预约';lead.history.unshift('已预约 · '+at.replace('T',' '));}
export function recordOutcome(lead,stage,reason){if(!['已沟通','已委托','已关闭','待跟进'].includes(stage))throw new Error('无效结果');if(stage==='已关闭'&&!reason.trim())throw new Error('请填写关闭原因');lead.stage=stage;lead.reason=reason;lead.history.unshift(stage+' · '+(reason||'已更新服务进展'));}
